from __future__ import annotations

"""Reporting-period calendar and play-to-period bucketing.

Each play has to land in exactly one reporting period so that the period's
payout pool is split among the plays that actually happened inside its window.
Periods are contiguous, non-overlapping, half-open windows ``[start, end)``.

Offline plays complicate this: a device can hold a play for days and then sync
it well after it happened. The period a play belongs to is fixed by when the
listener heard the track, not by when the report reached the backend.
"""

from royalty_models import ReportingPeriod, StreamPlay


class PeriodCalendar:
    """An ordered set of contiguous reporting periods."""

    def __init__(self, periods: list[ReportingPeriod]) -> None:
        if not periods:
            raise ValueError("at least one period is required")
        ordered = sorted(periods, key=lambda p: p.start_ms)
        self._validate_contiguity(ordered)
        self._periods: tuple[ReportingPeriod, ...] = tuple(ordered)
        self._by_id: dict[str, ReportingPeriod] = {p.period_id: p for p in ordered}

    @staticmethod
    def _validate_contiguity(ordered: list[ReportingPeriod]) -> None:
        seen_ids: set[str] = set()
        for period in ordered:
            if period.period_id in seen_ids:
                raise ValueError(f"duplicate period_id {period.period_id}")
            seen_ids.add(period.period_id)
        for earlier, later in zip(ordered, ordered[1:]):
            if later.start_ms < earlier.end_ms:
                raise ValueError("periods overlap")

    @property
    def periods(self) -> tuple[ReportingPeriod, ...]:
        return self._periods

    def period_ids(self) -> list[str]:
        return [p.period_id for p in self._periods]

    def get(self, period_id: str) -> ReportingPeriod:
        if period_id not in self._by_id:
            raise KeyError(period_id)
        return self._by_id[period_id]

    def first(self) -> ReportingPeriod:
        return self._periods[0]

    def last(self) -> ReportingPeriod:
        return self._periods[-1]

    def covers(self, timestamp_ms: int) -> bool:
        return any(
            period.start_ms <= timestamp_ms < period.end_ms for period in self._periods
        )

    def span_ms(self) -> tuple[int, int]:
        return (self._periods[0].start_ms, self._periods[-1].end_ms)


def _timestamp_for_bucketing(play: StreamPlay) -> int:
    """The timestamp used to place a play into a reporting period.

    Online plays are reported immediately, so their sync time and play time are
    effectively the same. Offline plays were cached locally and uploaded on the
    next sync, which is the moment the backend first learns about them.
    """

    if play.is_offline:
        return play.synced_at_ms
    return play.played_at_ms


def period_for_play(calendar: PeriodCalendar, play: StreamPlay) -> ReportingPeriod | None:
    """Return the period a play belongs to, or ``None`` if outside the calendar.

    A play with timestamp ``t`` belongs to the period whose window satisfies
    ``start_ms <= t < end_ms``.
    """

    stamp = _timestamp_for_bucketing(play)
    for period in calendar.periods:
        if period.start_ms <= stamp < period.end_ms:
            return period
    return None


def period_id_for_play(calendar: PeriodCalendar, play: StreamPlay) -> str | None:
    period = period_for_play(calendar, play)
    return period.period_id if period is not None else None


def bucket_plays(
    calendar: PeriodCalendar, plays: list[StreamPlay]
) -> dict[str, list[StreamPlay]]:
    """Group plays by the period they belong to.

    Plays that fall outside every period are dropped from the result. The
    returned dict only contains period ids that received at least one play.
    """

    buckets: dict[str, list[StreamPlay]] = {}
    for play in plays:
        period = period_for_play(calendar, play)
        if period is None:
            continue
        buckets.setdefault(period.period_id, []).append(play)
    return buckets


def plays_in_period(
    calendar: PeriodCalendar, period_id: str, plays: list[StreamPlay]
) -> list[StreamPlay]:
    """All plays that belong to one named period."""

    target = calendar.get(period_id)
    selected: list[StreamPlay] = []
    for play in plays:
        stamp = _timestamp_for_bucketing(play)
        if target.start_ms <= stamp < target.end_ms:
            selected.append(play)
    return selected


def out_of_calendar_plays(
    calendar: PeriodCalendar, plays: list[StreamPlay]
) -> list[StreamPlay]:
    """Plays whose bucketing timestamp lands outside every period window."""

    low, high = calendar.span_ms()
    stragglers: list[StreamPlay] = []
    for play in plays:
        stamp = _timestamp_for_bucketing(play)
        if stamp < low or stamp >= high:
            stragglers.append(play)
    return stragglers

