from __future__ import annotations

"""Ingestion pipeline for stream plays into per-period tallies.

Plays arrive in batches. Online batches are roughly real-time; offline batches
can land late, after an early reader has already looked at a period's totals.
Ingestion stores each play in the ledger (deduplicating by id), routes it to
its reporting period, and keeps per-period, per-rightsholder counts.
"""

from period_calendar import PeriodCalendar, period_for_play
from royalty_models import StreamPlay
from stream_ledger import StreamLedger


class IngestPipeline:
    def __init__(self, calendar: PeriodCalendar, ledger: StreamLedger | None = None) -> None:
        self._calendar = calendar
        self._ledger = ledger if ledger is not None else StreamLedger()
        # period_id -> rightsholder_id -> eligible play count
        self._period_counts: dict[str, dict[str, int]] = {}
        # period_id -> total eligible plays tallied so far
        self._period_totals: dict[str, int] = {}
        self._dropped: list[StreamPlay] = []
        self._batches_seen = 0
        # Memoized per-period totals to avoid re-summing on repeated reads.
        self._total_cache: dict[str, int] = {}

    @property
    def ledger(self) -> StreamLedger:
        return self._ledger

    @property
    def calendar(self) -> PeriodCalendar:
        return self._calendar

    def _tally(self, play: StreamPlay, period_id: str) -> None:
        bucket = self._period_counts.setdefault(period_id, {})
        bucket[play.rightsholder_id] = bucket.get(play.rightsholder_id, 0) + 1
        self._period_totals[period_id] = self._period_totals.get(period_id, 0) + 1

    def ingest_play(self, play: StreamPlay) -> bool:
        """Accept one play. Returns True if it was newly stored and tallied."""

        if not self._ledger.add(play):
            return False
        if not play.eligible:
            return True
        period = period_for_play(self._calendar, play)
        if period is None:
            self._dropped.append(play)
            return True
        self._tally(play, period.period_id)
        return True

    def ingest_batch(self, plays: list[StreamPlay]) -> int:
        """Ingest a batch of plays; returns how many were newly accepted."""

        self._batches_seen += 1
        accepted = 0
        for play in plays:
            if self.ingest_play(play):
                accepted += 1
        return accepted

    def batches_seen(self) -> int:
        return self._batches_seen

    def dropped_plays(self) -> list[StreamPlay]:
        return list(self._dropped)

    def counts_for_period(self, period_id: str) -> dict[str, int]:
        """Per-rightsholder eligible counts tallied for a period so far."""

        return dict(self._period_counts.get(period_id, {}))

    def eligible_total_for(self, period_id: str) -> int:
        """Eligible plays tallied for a period.

        The first read for a period is memoized so repeated reads during a
        reconciliation pass stay cheap.
        """

        if period_id not in self._total_cache:
            self._total_cache[period_id] = self._period_totals.get(period_id, 0)
        return self._total_cache[period_id]

    def live_eligible_total_for(self, period_id: str) -> int:
        """The current running tally for a period, ignoring any memoized value."""

        return self._period_totals.get(period_id, 0)

    def rightsholders_in_period(self, period_id: str) -> list[str]:
        return list(self._period_counts.get(period_id, {}).keys())

    def period_summary(self, period_id: str) -> dict[str, object]:
        return {
            "period_id": period_id,
            "total_eligible": self.eligible_total_for(period_id),
            "rightsholder_count": len(self.counts_for_period(period_id)),
            "counts": self.counts_for_period(period_id),
        }

