from __future__ import annotations

"""Helpers for building reporting calendars and payout pools.

These are convenience constructors so callers do not hand-assemble period
windows from raw millisecond math. A month here is modeled as a fixed-length
window for simplicity; the boundaries are what matter for bucketing.
"""

from royalty_models import PayoutPool, ReportingPeriod

DAY_MS = 24 * 60 * 60 * 1000


def day_ms(days: int) -> int:
    return days * DAY_MS


def month_window(period_id: str, start_ms: int, length_days: int = 30) -> ReportingPeriod:
    """Build a half-open reporting window of ``length_days`` from ``start_ms``."""

    if length_days <= 0:
        raise ValueError("length_days must be positive")
    return ReportingPeriod(
        period_id=period_id,
        start_ms=start_ms,
        end_ms=start_ms + day_ms(length_days),
    )


def sequential_months(
    first_id: str,
    second_id: str,
    start_ms: int = 0,
    length_days: int = 30,
) -> list[ReportingPeriod]:
    """Two back-to-back periods sharing a boundary at the month edge."""

    first = month_window(first_id, start_ms, length_days)
    second = month_window(second_id, first.end_ms, length_days)
    return [first, second]


def build_pool(period_id: str, amount_cents: int, currency: str = "USD") -> PayoutPool:
    return PayoutPool(period_id=period_id, currency=currency, amount_cents=amount_cents)


def pools_for(period_amounts: dict[str, int], currency: str = "USD") -> list[PayoutPool]:
    return [
        build_pool(period_id, amount, currency)
        for period_id, amount in period_amounts.items()
    ]


def boundary_ms(period: ReportingPeriod) -> tuple[int, int]:
    """The inclusive start and exclusive end of a period."""

    return (period.start_ms, period.end_ms)


def consecutive_months(
    period_ids: list[str],
    start_ms: int = 0,
    length_days: int = 30,
) -> list[ReportingPeriod]:
    """Build any number of back-to-back periods from a list of ids."""

    if not period_ids:
        raise ValueError("at least one period id is required")
    windows: list[ReportingPeriod] = []
    cursor = start_ms
    for period_id in period_ids:
        window = month_window(period_id, cursor, length_days)
        windows.append(window)
        cursor = window.end_ms
    return windows


def is_at_boundary(period: ReportingPeriod, timestamp_ms: int) -> bool:
    """True when a timestamp sits exactly on either edge of a period."""

    return timestamp_ms == period.start_ms or timestamp_ms == period.end_ms

