from __future__ import annotations

"""Cent-exact distribution of a pool across weighted shares.

Pro-rata math produces fractional cents that cannot be paid out. We floor each
party's raw share to whole cents, then hand out the leftover cents one at a
time to the parties with the largest fractional remainders. This keeps the sum
of payouts exactly equal to the pool: no cent is invented or lost.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class WeightedShare:
    key: str
    weight: int
    raw_cents: float
    floor_cents: int
