from __future__ import annotations

"""Domain models for StreamShare royalty allocation.

A reporting period is a half-open window ``[start_ms, end_ms)`` in epoch
milliseconds. Within a period there is a single payout pool measured in
integer minor units (cents). Each eligible stream play counts once toward the
rightsholder who owns the played track. A rightsholder's payout is a pro-rata
share of the pool:

    payout = pool * (their eligible streams / total eligible streams)

Plays arrive from several sources. Online plays are reported close to when
they happen. Offline plays are cached on a device and synced later, sometimes
days after the listener actually heard the track, so the time a play *arrives*
and the time it was *played* can differ a lot.
"""

from dataclasses import dataclass, field


def _require_text(value: str, field_name: str) -> None:
    if not value or not value.strip():
        raise ValueError(f"{field_name} is required")


@dataclass(frozen=True)
class StreamPlay:
    """A single eligible stream of a track by some listener.

    ``played_at_ms`` is when the listener actually heard the track. For online
    plays this is close to ``synced_at_ms``; for offline plays the sync can
    land much later. ``play_id`` is globally unique so the same play can be
    re-delivered without being counted twice.
    """

    play_id: str
    track_id: str
    rightsholder_id: str
    played_at_ms: int
    synced_at_ms: int
    source: str = "online"
    eligible: bool = True

    def __post_init__(self) -> None:
        _require_text(self.play_id, "play_id")
        _require_text(self.track_id, "track_id")
        _require_text(self.rightsholder_id, "rightsholder_id")
        if self.played_at_ms < 0:
            raise ValueError("played_at_ms must be non-negative")
        if self.synced_at_ms < 0:
            raise ValueError("synced_at_ms must be non-negative")
        if self.source not in {"online", "offline"}:
            raise ValueError("source must be online or offline")

    @property
    def is_offline(self) -> bool:
        return self.source == "offline"

    @classmethod
    def from_raw(cls, raw: dict) -> "StreamPlay":
        return cls(
            play_id=str(raw.get("play_id", "")),
            track_id=str(raw.get("track_id", "")),
            rightsholder_id=str(raw.get("rightsholder_id", "")),
            played_at_ms=int(raw.get("played_at_ms", 0)),
            synced_at_ms=int(raw.get("synced_at_ms", raw.get("played_at_ms", 0))),
            source=str(raw.get("source", "online")),
            eligible=bool(raw.get("eligible", True)),
        )


@dataclass(frozen=True)
class ReportingPeriod:
    """A half-open reporting window ``[start_ms, end_ms)``.

    A play belongs to this period when ``start_ms <= played_at_ms < end_ms``.
    The start is inclusive and the end is exclusive, so a play recorded exactly
    at ``end_ms`` belongs to the next period, never to this one.
    """

    period_id: str
    start_ms: int
    end_ms: int

    def __post_init__(self) -> None:
        _require_text(self.period_id, "period_id")
        if self.start_ms < 0:
            raise ValueError("start_ms must be non-negative")
        if self.end_ms <= self.start_ms:
            raise ValueError("end_ms must be greater than start_ms")

    @property
    def length_ms(self) -> int:
        return self.end_ms - self.start_ms


@dataclass(frozen=True)
class Rightsholder:
    """A label, distributor, or artist account that receives payouts."""

    rightsholder_id: str
    display_name: str
    payee_account: str

    def __post_init__(self) -> None:
        _require_text(self.rightsholder_id, "rightsholder_id")
        _require_text(self.display_name, "display_name")
        _require_text(self.payee_account, "payee_account")


@dataclass(frozen=True)
class PayoutPool:
    """The money available to split across a period, in integer cents."""

    period_id: str
    currency: str
    amount_cents: int

    def __post_init__(self) -> None:
        _require_text(self.period_id, "period_id")
        _require_text(self.currency, "currency")
        if self.amount_cents < 0:
            raise ValueError("amount_cents must be non-negative")


@dataclass(frozen=True)
class RightsholderShare:
    """The computed payout for one rightsholder in a period."""

    rightsholder_id: str
    eligible_streams: int
    raw_share_cents: float
    payout_cents: int

    def __post_init__(self) -> None:
        _require_text(self.rightsholder_id, "rightsholder_id")
        if self.eligible_streams < 0:
            raise ValueError("eligible_streams must be non-negative")
        if self.payout_cents < 0:
            raise ValueError("payout_cents must be non-negative")


@dataclass(frozen=True)
class AllocationResult:
    """Outcome of allocating one pool across the period's rightsholders."""

    period_id: str
    currency: str
    pool_cents: int
    total_eligible_streams: int
    shares: tuple[RightsholderShare, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        _require_text(self.period_id, "period_id")
        _require_text(self.currency, "currency")
        if self.pool_cents < 0:
            raise ValueError("pool_cents must be non-negative")
        if self.total_eligible_streams < 0:
            raise ValueError("total_eligible_streams must be non-negative")

    @property
    def allocated_cents(self) -> int:
        return sum(share.payout_cents for share in self.shares)

    @property
    def residual_cents(self) -> int:
        return self.pool_cents - self.allocated_cents

    def share_for(self, rightsholder_id: str) -> RightsholderShare | None:
        for share in self.shares:
            if share.rightsholder_id == rightsholder_id:
                return share
        return None

    def payout_map(self) -> dict[str, int]:
        return {share.rightsholder_id: share.payout_cents for share in self.shares}


def build_play(
    play_id: str,
    track_id: str,
    rightsholder_id: str,
    played_at_ms: int,
    synced_at_ms: int | None = None,
    source: str = "online",
    eligible: bool = True,
) -> StreamPlay:
    """Convenience constructor used by callers and tests."""

    return StreamPlay(
        play_id=play_id,
        track_id=track_id,
        rightsholder_id=rightsholder_id,
        played_at_ms=played_at_ms,
        synced_at_ms=played_at_ms if synced_at_ms is None else synced_at_ms,
        source=source,
        eligible=eligible,
    )

