from __future__ import annotations

"""In-memory ledger of accepted stream plays.

The ledger is keyed by ``play_id`` so a re-delivered play is stored once. It
also tracks the order in which plays were accepted, which lets callers tell
"plays seen so far" apart from "all plays for the period" when late batches
arrive after an early read.
"""

from royalty_models import StreamPlay


class StreamLedger:
    def __init__(self) -> None:
        self._plays: dict[str, StreamPlay] = {}
        self._accept_order: list[str] = []

    def add(self, play: StreamPlay) -> bool:
        """Record a play. Returns False if this play_id was already stored."""

        if play.play_id in self._plays:
            return False
        self._plays[play.play_id] = play
        self._accept_order.append(play.play_id)
        return True

    def add_many(self, plays: list[StreamPlay]) -> int:
        accepted = 0
        for play in plays:
            if self.add(play):
                accepted += 1
        return accepted

    def has(self, play_id: str) -> bool:
        return play_id in self._plays

    def get(self, play_id: str) -> StreamPlay | None:
        return self._plays.get(play_id)

    def __len__(self) -> int:
        return len(self._plays)

    def all_plays(self) -> list[StreamPlay]:
        """Every accepted play, in the order it was accepted."""

        return [self._plays[pid] for pid in self._accept_order]

    def eligible_plays(self) -> list[StreamPlay]:
        return [play for play in self.all_plays() if play.eligible]

    def plays_by_rightsholder(self, rightsholder_id: str) -> list[StreamPlay]:
        return [
            play
            for play in self.all_plays()
            if play.rightsholder_id == rightsholder_id
        ]

    def rightsholder_ids(self) -> list[str]:
        seen: list[str] = []
        for play in self.all_plays():
            if play.rightsholder_id not in seen:
                seen.append(play.rightsholder_id)
        return seen

    def snapshot_count(self) -> int:
        """How many plays have been accepted so far."""

        return len(self._accept_order)

